                          ? ` & ${initialRecord.addOns.join(", ")}`
                          : " treatment"}
                      </p>
                    </div>
                    <span className={cn(
                      "shrink-0 inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-bold shadow-xs",
                      isDone
