                        : isCurrent
                          ? "bg-purple-100 text-purple-700 border border-purple-200"
                          : "bg-stone-100 text-slate-500 border border-stone-200/80 font-medium"
                    )}>
                      {isDone ? "Done" : isCurrent ? "Live" : "Pending"}
                    </span>
                  </div>
                </div>
